function Register() {
  return (
    <div>
      <h1 className='text-center mt-5'>Hotel CRM</h1>
      <p className='text-center mb-5'>Sign in to manage your hotel</p>
      <div className='form-container'></div>
      {/* Registration form goes here */}
    </div>

  );
}

export default Register;
